import { Treemap, type TreemapDrillDetail, type TreemapNode } from '@absoluteui/components/treemap';

const data: TreemapNode[] = [
  { id: 'eng', label: 'Engineering', children: [{ id: 'web', label: 'Web', value: 30 }, { id: 'api', label: 'API', value: 20 }] },
  { id: 'ops', label: 'Operations', value: 25 },
  { id: 'people', label: 'People', value: 25 },
];
const host = document.createElement('div');
document.body.append(host);
const chart = Treemap.create(host, { label: 'Budget', data, valueFormat: { style: 'currency', currency: 'EUR', notation: 'compact' } });
host.addEventListener('aui-drill', (event) => {
  const { path } = (event as CustomEvent<TreemapDrillDetail>).detail;
  host.dataset.path = path.join('/');
});
chart.drillTo('eng');

import { Treemap } from '@absoluteui/components/treemap';
import { downloadChart } from '@absoluteui/components/chart-export';

const host = document.querySelector<HTMLElement>('#disk');
const button = document.querySelector<HTMLButtonElement>('#export');
if (host && button) {
  const chart = Treemap.create(host, {
    label: 'Disk usage',
    data: [
      { id: 'video', label: 'Video', value: 420 },
      { id: 'photos', label: 'Photos', value: 180 },
      { id: 'apps', label: 'Apps', value: 95 },
      { id: 'docs', label: 'Documents', value: 30, color: 6 },
    ],
    drillDown: false,
    valueFormat: { style: 'unit', unit: 'gigabyte' },
    height: 240,
  });
  button.addEventListener('click', () => {
    void downloadChart(chart, { format: 'png', fileName: 'disk-usage' });
  });
}
